CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, nickname text NOT NULL, phone text, phone_verification_status text NOT NULL CHECK (phone_verification_status IN ('verified','unverified')), privacy_contract_version text, privacy_accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_wechat_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), identity_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS authentication_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS browser_login_sessions (id uuid PRIMARY KEY, status text NOT NULL CHECK (status IN ('pending','approved','rejected','expired')), qr_code_url text NOT NULL, expires_at timestamptz NOT NULL, approved_by uuid REFERENCES users(id), web_token_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS role_assignments (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK (role IN ('clerk','manager','owner')), assigned_at timestamptz NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS role_assignments_one_active_role ON role_assignments(user_id);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY, actor_id uuid, action text NOT NULL, object_id uuid, reason text, request_id text, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS areas (id uuid PRIMARY KEY, name text NOT NULL, grid_columns integer NOT NULL CHECK (grid_columns BETWEEN 4 AND 48), grid_rows integer NOT NULL CHECK (grid_rows BETWEEN 4 AND 80), locked boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS table_layouts (id uuid PRIMARY KEY, area_id uuid NOT NULL REFERENCES areas(id), number integer NOT NULL, seat_count integer NOT NULL CHECK (seat_count BETWEEN 1 AND 99), grid_x integer NOT NULL, grid_y integer NOT NULL, enabled boolean NOT NULL DEFAULT true, UNIQUE(area_id, number), UNIQUE(area_id, grid_x, grid_y));
CREATE TABLE IF NOT EXISTS seats (id uuid PRIMARY KEY, table_id uuid NOT NULL REFERENCES table_layouts(id), seat_number integer NOT NULL, UNIQUE(table_id, seat_number));
CREATE TABLE IF NOT EXISTS table_splits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), table_id uuid NOT NULL REFERENCES table_layouts(id), new_table_count integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_sessions (id uuid PRIMARY KEY, table_id uuid NOT NULL REFERENCES table_layouts(id), user_id uuid REFERENCES users(id), status text NOT NULL CHECK (status IN ('active','paused','companion','cancelled','settled')), started_at timestamptz NOT NULL, duration_minutes integer NOT NULL CHECK (duration_minutes > 0));
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY, name text NOT NULL, unit_price_cents bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS service_products (product_id uuid PRIMARY KEY REFERENCES products(id), duration_minutes integer, price_cents bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory_items (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), quantity bigint NOT NULL DEFAULT 0 CHECK (quantity >= 0), alert_at bigint NOT NULL DEFAULT 0 CHECK (alert_at >= 0));
CREATE TABLE IF NOT EXISTS inventory_movements (id uuid PRIMARY KEY, inventory_item_id uuid NOT NULL REFERENCES inventory_items(id), kind text NOT NULL, quantity_delta bigint NOT NULL, reason text, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_records (id uuid PRIMARY KEY, supplier_name text NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory_adjustments (id uuid PRIMARY KEY, inventory_item_id uuid NOT NULL REFERENCES inventory_items(id), quantity_delta bigint NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY, table_session_id uuid REFERENCES service_sessions(id), user_id uuid REFERENCES users(id), status text NOT NULL CHECK (status IN ('draft','paid','refunded','voided')), receivable_cents bigint NOT NULL DEFAULT 0, paid_cents bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), product_id uuid REFERENCES products(id), name text, quantity integer NOT NULL, unit_price_cents bigint NOT NULL);
CREATE TABLE IF NOT EXISTS payment_entries (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), method text NOT NULL, amount_cents bigint NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS order_discounts (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), kind text NOT NULL, amount_cents bigint, rate_basis_points bigint, reason text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS refunds (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), amount_cents bigint NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS backups (id uuid PRIMARY KEY, created_at timestamptz NOT NULL, data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS restorations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), backup_id uuid NOT NULL REFERENCES backups(id), pre_restore_backup_id uuid REFERENCES backups(id), created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys (key text PRIMARY KEY, status integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pindou_state (id smallint PRIMARY KEY CHECK (id = 1), data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
